"""Recursive-descent parser producing a small AST for MicroVM."""

from __future__ import annotations

import dataclasses
from collections.abc import Callable

from .errors import ParseError
from .lexer import Token, tokenize


@dataclasses.dataclass
class Literal:
    value: object  # int, float, str or bool; the Python type is the MicroVM type


@dataclasses.dataclass
class Name:
    name: str
    offset: int


@dataclasses.dataclass
class Unary:
    op: str  # "-" or "not"
    operand: object


@dataclasses.dataclass
class Binary:
    op: str
    left: object
    right: object


@dataclasses.dataclass
class Logical:
    op: str  # "and" or "or"; short-circuiting
    left: object
    right: object


@dataclasses.dataclass
class Let:
    name: str
    offset: int
    value: object


@dataclasses.dataclass
class Assign:
    name: str
    offset: int
    value: object


@dataclasses.dataclass
class Print:
    value: object


@dataclasses.dataclass
class If:
    cond: object
    then_body: object
    else_body: object | None


@dataclasses.dataclass
class While:
    cond: object
    body: object


@dataclasses.dataclass
class Block:
    stmts: list[object]


_COMPARE_OPS: tuple[str, ...] = ("==", "!=", "<", "<=", ">", ">=")


def parse(src: str) -> Block:
    """Parse ``src`` into a Block holding the top-level statements."""
    parser = _Parser(src)
    stmts: list[object] = []
    while parser.peek() is not None:
        stmts.append(parser.statement())
    return Block(stmts)


class _Parser:
    def __init__(self, src: str) -> None:
        self.tokens: list[Token] = tokenize(src)
        self.end: int = len(src)
        self.pos: int = 0

    # ----- token helpers -------------------------------------------------
    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self) -> Token:
        token = self.peek()
        if token is None:
            raise self.error("unexpected end of input")
        self.pos += 1
        return token

    def check(self, kind: str, text: str | None = None) -> bool:
        token = self.peek()
        return token is not None and token.kind == kind and (text is None or token.text == text)

    def expect(self, kind: str, text: str | None = None) -> Token:
        if not self.check(kind, text):
            raise self.error(f"expected {text if text is not None else kind}")
        return self.advance()

    def next_is(self, ops: tuple[str, ...]) -> bool:
        token = self.peek()
        return token is not None and token.kind in ("OP", "KEYWORD") and token.text in ops

    def error(self, message: str) -> ParseError:
        token = self.peek()
        return ParseError(message, token.offset if token is not None else self.end)

    # ----- statements ----------------------------------------------------
    def statement(self) -> object:
        if self.check("KEYWORD", "let"):
            return self.let_stmt()
        if self.check("KEYWORD", "print"):
            return self.print_stmt()
        if self.check("KEYWORD", "if"):
            return self.if_stmt()
        if self.check("KEYWORD", "while"):
            return self.while_stmt()
        if self.check("OP", "{"):
            return self.block()
        if self.check("IDENT"):
            return self.assign_stmt()
        raise self.error("expected a statement")

    def let_stmt(self) -> Let:
        self.advance()
        name = self.expect("IDENT")
        self.expect("OP", "=")
        value = self.expression()
        self.expect("OP", ";")
        return Let(name.text, name.offset, value)

    def assign_stmt(self) -> Assign:
        name = self.expect("IDENT")
        self.expect("OP", "=")
        value = self.expression()
        self.expect("OP", ";")
        return Assign(name.text, name.offset, value)

    def print_stmt(self) -> Print:
        self.advance()
        value = self.expression()
        self.expect("OP", ";")
        return Print(value)

    def if_stmt(self) -> If:
        self.advance()
        cond = self.expression()
        then_body = self.block()
        else_body: object | None = None
        if self.check("KEYWORD", "else"):
            self.advance()
            else_body = self.if_stmt() if self.check("KEYWORD", "if") else self.block()
        return If(cond, then_body, else_body)

    def while_stmt(self) -> While:
        self.advance()
        cond = self.expression()
        return While(cond, self.block())

    def block(self) -> Block:
        self.expect("OP", "{")
        stmts: list[object] = []
        while not self.check("OP", "}"):
            if self.peek() is None:
                raise self.error("expected '}'")
            stmts.append(self.statement())
        self.advance()
        return Block(stmts)

    # ----- expressions ---------------------------------------------------
    def expression(self) -> object:
        return self.or_expr()

    def left_assoc(
        self,
        operand: Callable[[], object],
        ops: tuple[str, ...],
        make: Callable[[str, object, object], object],
    ) -> object:
        node = operand()
        while self.next_is(ops):
            op = self.advance().text
            node = make(op, node, operand())
        return node

    def or_expr(self) -> object:
        return self.left_assoc(self.and_expr, ("or",), Logical)

    def and_expr(self) -> object:
        return self.left_assoc(self.not_expr, ("and",), Logical)

    def not_expr(self) -> object:
        if self.next_is(("not",)):
            self.advance()
            return Unary("not", self.not_expr())
        return self.comparison()

    def comparison(self) -> object:
        left = self.additive()
        if not self.next_is(_COMPARE_OPS):
            return left
        op = self.advance().text
        right = self.additive()
        if self.next_is(_COMPARE_OPS):
            raise self.error("comparison operators cannot be chained")
        return Binary(op, left, right)

    def additive(self) -> object:
        return self.left_assoc(self.multiplicative, ("+", "-"), Binary)

    def multiplicative(self) -> object:
        return self.left_assoc(self.unary, ("*", "/", "%"), Binary)

    def unary(self) -> object:
        if self.check("OP", "-"):
            self.advance()
            return Unary("-", self.unary())
        return self.primary()

    def primary(self) -> object:
        token = self.peek()
        if token is None:
            raise self.error("expected an expression")
        if token.kind in ("INT", "FLOAT", "STRING"):
            self.advance()
            return Literal(token.value)
        if token.kind == "KEYWORD" and token.text in ("true", "false"):
            self.advance()
            return Literal(token.text == "true")
        if token.kind == "IDENT":
            self.advance()
            return Name(token.text, token.offset)
        if token.kind == "OP" and token.text == "(":
            self.advance()
            inner = self.expression()
            self.expect("OP", ")")
            return inner
        raise self.error("expected an expression")

"""Stack virtual machine that executes compiled Programs."""

from __future__ import annotations

import operator
from typing import TYPE_CHECKING

from .errors import StepLimitError, VMRuntimeError

if TYPE_CHECKING:
    from .compiler import Instr, Program

_UNSET = object()
_BINARY_SYMBOLS: dict[str, str] = {
    "ADD": "+", "SUB": "-", "MUL": "*", "DIV": "/", "MOD": "%",
    "EQ": "==", "NE": "!=", "LT": "<", "LE": "<=", "GT": ">", "GE": ">=",
}
_UNARY_SYMBOLS: dict[str, str] = {"NEG": "-", "NOT": "not"}
_ARITH_OPS: dict[str, Callable[[object, object], object]] = {
    "+": operator.add, "-": operator.sub, "*": operator.mul,
    "/": operator.truediv, "%": operator.mod,
}
_ORDER_OPS: dict[str, Callable[[object, object], bool]] = {
    "<": operator.lt, "<=": operator.le, ">": operator.gt, ">=": operator.ge,
}
_CONDITIONAL_OPS: frozenset[str] = frozenset({"JUMP", "JUMP_IF_FALSE"})

from collections.abc import Callable  # noqa: E402  (used in annotations above)


def _is_bool(value: object) -> bool:
    return type(value) is bool


def _is_num(value: object) -> bool:
    return type(value) in (int, float)


def binary_op(symbol: str, left: object, right: object) -> object:
    """Apply a binary operator under MicroVM rules; shared with the optimizer."""
    if symbol == "==":
        return _equal(left, right)
    if symbol == "!=":
        return not _equal(left, right)
    if symbol in _ORDER_OPS:
        return _order(symbol, left, right)
    return _arithmetic(symbol, left, right)


def unary_op(symbol: str, operand: object) -> object:
    """Apply ``not`` or unary minus under MicroVM rules."""
    if symbol == "not":
        if not _is_bool(operand):
            raise VMRuntimeError("'not' requires a BOOL operand")
        return not operand
    if not _is_num(operand):
        raise VMRuntimeError("unary '-' requires a number")
    return -operand  # type: ignore[operator]


def _equal(left: object, right: object) -> bool:
    if _is_bool(left) or _is_bool(right):
        return _is_bool(left) and _is_bool(right) and left == right
    if _is_num(left) and _is_num(right):
        return left == right  # type: ignore[operator]
    if type(left) is str and type(right) is str:
        return left == right
    return False


def _order(symbol: str, left: object, right: object) -> bool:
    comparable = (_is_num(left) and _is_num(right)) or (
        type(left) is str and type(right) is str
    )
    if not comparable:
        raise VMRuntimeError(f"'{symbol}' requires two numbers or two strings")
    return _ORDER_OPS[symbol](left, right)


def _arithmetic(symbol: str, left: object, right: object) -> object:
    if symbol == "+" and type(left) is str and type(right) is str:
        return left + right
    if not (_is_num(left) and _is_num(right)):
        raise VMRuntimeError(f"'{symbol}' requires numbers")
    if symbol in ("/", "%") and right == 0:
        raise VMRuntimeError("division by zero")
    if symbol == "%" and not (type(left) is int and type(right) is int):
        raise VMRuntimeError("'%' requires INT operands")
    try:
        return _ARITH_OPS[symbol](left, right)
    except OverflowError as exc:
        raise VMRuntimeError("numeric overflow") from exc


def render(value: object) -> str:
    """Render a value for ``print``."""
    if _is_bool(value):
        return "true" if value else "false"
    if type(value) is str:
        return value
    try:
        return str(value)
    except ValueError as exc:
        raise VMRuntimeError("integer too large to print") from exc


class _Machine:
    """Mutable execution state for one run of a Program."""

    def __init__(self, program: Program) -> None:
        self.program = program
        self.stack: list[object] = []
        self.slots: list[object] = [_UNSET] * len(program.names)
        self.output: list[str] = []
        self.ip: int = 0

    def run(self, step_limit: int) -> list[str]:
        steps = 0
        while True:
            instr = self.fetch()
            steps += 1
            if steps > step_limit:
                raise StepLimitError(f"step limit of {step_limit} exceeded")
            self.ip += 1
            if instr.op == "HALT":
                return self.output
            self.dispatch(instr)

    def fetch(self) -> Instr:
        instructions = self.program.instructions
        if not 0 <= self.ip < len(instructions):
            raise VMRuntimeError(f"instruction pointer {self.ip} is out of range")
        return instructions[self.ip]

    def pop(self) -> object:
        if not self.stack:
            raise VMRuntimeError("operand stack underflow")
        return self.stack.pop()

    def dispatch(self, instr: Instr) -> None:
        op = instr.op
        if op in _BINARY_SYMBOLS:
            right = self.pop()
            left = self.pop()
            self.stack.append(binary_op(_BINARY_SYMBOLS[op], left, right))
        elif op in _UNARY_SYMBOLS:
            self.stack.append(unary_op(_UNARY_SYMBOLS[op], self.pop()))
        elif op in ("CONST", "LOAD", "STORE") or op in _CONDITIONAL_OPS:
            if instr.arg is None:
                raise VMRuntimeError(f"{op} is missing its argument")
            self.dispatch_arg(op, instr.arg)
        else:
            self.dispatch_plain(op)

    def dispatch_arg(self, op: str, arg: int) -> None:
        if op == "CONST":
            self.stack.append(self.constant(arg))
        elif op == "LOAD":
            self.stack.append(self.read(arg))
        elif op == "STORE":
            self.write(arg, self.pop())
        elif op == "JUMP":
            self.ip = arg
        else:
            cond = self.pop()
            if not _is_bool(cond):
                raise VMRuntimeError("condition must be a BOOL")
            if cond is False:
                self.ip = arg

    def dispatch_plain(self, op: str) -> None:
        if op == "PRINT":
            self.output.append(render(self.pop()))
        elif op == "POP":
            self.pop()
        else:
            raise VMRuntimeError(f"unknown opcode {op}")

    def constant(self, index: int) -> object:
        if not 0 <= index < len(self.program.constants):
            raise VMRuntimeError(f"constant index {index} out of range")
        return self.program.constants[index]

    def slot(self, index: int) -> int:
        if not 0 <= index < len(self.slots):
            raise VMRuntimeError(f"variable slot {index} out of range")
        return index

    def read(self, index: int) -> object:
        slot = self.slot(index)
        value = self.slots[slot]
        if value is _UNSET:
            name = self.program.names[slot]
            raise VMRuntimeError(f"variable '{name}' read before assignment")
        return value

    def write(self, index: int, value: object) -> None:
        self.slots[self.slot(index)] = value


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    """Run ``program`` and return its printed lines.

    Raises StepLimitError once more than ``step_limit`` instructions have run.
    """
    if type(step_limit) is not int or step_limit < 1:
        raise ValueError("step_limit must be a positive int")
    return _Machine(program).run(step_limit)

"""Constant folding over the parser AST. Folding never changes observable behaviour."""

from __future__ import annotations

from .errors import VMRuntimeError
from .parser import Assign, Binary, Block, If, Let, Literal, Logical, Print, Unary, While
from .vm import binary_op, unary_op


def fold_constants(node: object) -> object:
    """Return a copy of ``node`` with literal sub-expressions folded where safe."""
    if isinstance(node, Block):
        return Block([fold_constants(stmt) for stmt in node.stmts])
    if isinstance(node, Let):
        return Let(node.name, node.offset, fold_constants(node.value))
    if isinstance(node, Assign):
        return Assign(node.name, node.offset, fold_constants(node.value))
    if isinstance(node, Print):
        return Print(fold_constants(node.value))
    if isinstance(node, If):
        return _fold_if(node)
    if isinstance(node, While):
        return While(fold_constants(node.cond), fold_constants(node.body))
    if isinstance(node, Unary):
        return _fold_unary(node)
    if isinstance(node, Binary):
        return _fold_binary(node)
    if isinstance(node, Logical):
        return _fold_logical(node)
    return node


def _fold_if(node: If) -> If:
    else_body = None if node.else_body is None else fold_constants(node.else_body)
    return If(fold_constants(node.cond), fold_constants(node.then_body), else_body)


def _fold_unary(node: Unary) -> object:
    operand = fold_constants(node.operand)
    if isinstance(operand, Literal):
        try:
            return Literal(unary_op(node.op, operand.value))
        except VMRuntimeError:
            pass  # would fail at run time; keep it so the error still happens
    return Unary(node.op, operand)


def _fold_binary(node: Binary) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if isinstance(left, Literal) and isinstance(right, Literal):
        try:
            return Literal(binary_op(node.op, left.value, right.value))
        except VMRuntimeError:
            pass  # would fail at run time; keep it so the error still happens
    return Binary(node.op, left, right)


def _fold_logical(node: Logical) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if isinstance(left, Literal) and type(left.value) is bool:
        # Short-circuit: the right side would never be evaluated, so it may be dropped.
        if node.op == "and" and left.value is False:
            return Literal(False)
        if node.op == "or" and left.value is True:
            return Literal(True)
        if isinstance(right, Literal) and type(right.value) is bool:
            folded = (left.value and right.value) if node.op == "and" else (left.value or right.value)
            return Literal(folded)
    return Logical(node.op, left, right)

"""Bytecode generation: scope checking, slot allocation and code emission."""

from __future__ import annotations

import dataclasses

from .errors import CompileError
from .optimizer import fold_constants
from .parser import (
    Assign, Binary, Block, If, Let, Literal, Logical, Name, Print, Unary, While, parse,
)

_BINARY_OPCODES: dict[str, str] = {
    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
}
_UNARY_OPCODES: dict[str, str] = {"-": "NEG", "not": "NOT"}


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None  # None exactly when the opcode takes no argument


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


class _Scope:
    """Checks declarations in source order and assigns variable slots."""

    def __init__(self) -> None:
        self.names: list[str] = []
        self.slots: dict[str, int] = {}

    def declare(self, name: str) -> None:
        if name in self.slots:
            raise CompileError(f"variable '{name}' is already declared")
        self.slots[name] = len(self.names)
        self.names.append(name)

    def require(self, name: str) -> None:
        if name not in self.slots:
            raise CompileError(f"variable '{name}' is not declared")

    def check_stmt(self, node: object) -> None:
        if isinstance(node, Block):
            for stmt in node.stmts:
                self.check_stmt(stmt)
        elif isinstance(node, Let):
            self.check_expr(node.value)
            self.declare(node.name)
        elif isinstance(node, Assign):
            self.check_expr(node.value)
            self.require(node.name)
        elif isinstance(node, Print):
            self.check_expr(node.value)
        elif isinstance(node, If):
            self.check_expr(node.cond)
            self.check_stmt(node.then_body)
            if node.else_body is not None:
                self.check_stmt(node.else_body)
        elif isinstance(node, While):
            self.check_expr(node.cond)
            self.check_stmt(node.body)

    def check_expr(self, node: object) -> None:
        if isinstance(node, Name):
            self.require(node.name)
        elif isinstance(node, Unary):
            self.check_expr(node.operand)
        elif isinstance(node, (Binary, Logical)):
            self.check_expr(node.left)
            self.check_expr(node.right)


class _CodeGen:
    """Emits instructions for a checked, optionally folded AST."""

    def __init__(self, slots: dict[str, int]) -> None:
        self.slots = slots
        self.constants: list[object] = []
        self.code: list[Instr] = []
        self._pool: dict[tuple[str, str], int] = {}

    def emit(self, op: str, arg: int | None = None) -> int:
        self.code.append(Instr(op, arg))
        return len(self.code) - 1

    def patch(self, index: int, target: int) -> None:
        self.code[index] = Instr(self.code[index].op, target)

    def here(self) -> int:
        return len(self.code)

    def const_index(self, value: object) -> int:
        # repr distinguishes 0.0 from -0.0 and 1 from True; the type name separates 1 from 1.0.
        key = (type(value).__name__, repr(value))
        if key not in self._pool:
            self._pool[key] = len(self.constants)
            self.constants.append(value)
        return self._pool[key]

    def emit_const(self, value: object) -> None:
        self.emit("CONST", self.const_index(value))

    def stmt(self, node: object) -> None:
        if isinstance(node, Block):
            for item in node.stmts:
                self.stmt(item)
        elif isinstance(node, (Let, Assign)):
            self.expr(node.value)
            self.emit("STORE", self.slots[node.name])
        elif isinstance(node, Print):
            self.expr(node.value)
            self.emit("PRINT")
        elif isinstance(node, If):
            self.if_stmt(node)
        elif isinstance(node, While):
            self.while_stmt(node)

    def if_stmt(self, node: If) -> None:
        self.expr(node.cond)
        to_else = self.emit("JUMP_IF_FALSE", 0)
        self.stmt(node.then_body)
        if node.else_body is None:
            self.patch(to_else, self.here())
            return
        to_end = self.emit("JUMP", 0)
        self.patch(to_else, self.here())
        self.stmt(node.else_body)
        self.patch(to_end, self.here())

    def while_stmt(self, node: While) -> None:
        start = self.here()
        self.expr(node.cond)
        to_end = self.emit("JUMP_IF_FALSE", 0)
        self.stmt(node.body)
        self.emit("JUMP", start)
        self.patch(to_end, self.here())

    def expr(self, node: object) -> None:
        if isinstance(node, Literal):
            self.emit_const(node.value)
        elif isinstance(node, Name):
            self.emit("LOAD", self.slots[node.name])
        elif isinstance(node, Unary):
            self.expr(node.operand)
            self.emit(_UNARY_OPCODES[node.op])
        elif isinstance(node, Binary):
            self.expr(node.left)
            self.expr(node.right)
            self.emit(_BINARY_OPCODES[node.op])
        elif isinstance(node, Logical):
            self.logical(node)

    def logical(self, node: Logical) -> None:
        # NOT NOT re-checks that the operand is BOOL and leaves its value unchanged.
        self.expr(node.left)
        to_false_path = self.emit("JUMP_IF_FALSE", 0)
        if node.op == "and":
            self.expr(node.right)
            self.emit("NOT")
            self.emit("NOT")
            to_end = self.emit("JUMP", 0)
            self.patch(to_false_path, self.here())
            self.emit_const(False)
        else:
            self.emit_const(True)
            to_end = self.emit("JUMP", 0)
            self.patch(to_false_path, self.here())
            self.expr(node.right)
            self.emit("NOT")
            self.emit("NOT")
        self.patch(to_end, self.here())


def compile_source(src: str, *, optimize: bool = False) -> Program:
    """Compile MicroVM source into a Program.

    Scope checks run on the unfolded AST so that folding cannot hide a CompileError.
    """
    tree = parse(src)
    scope = _Scope()
    scope.check_stmt(tree)
    if optimize:
        tree = fold_constants(tree)
    gen = _CodeGen(scope.slots)
    gen.stmt(tree)
    gen.emit("HALT")
    return Program(constants=gen.constants, names=scope.names, instructions=gen.code)

"""Binary codec for compiled Programs (magic, version, checksummed body)."""

from __future__ import annotations

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import ARGUMENT_OPCODES, OPCODE_NUMBERS, OPCODES

MAGIC: bytes = b"MVM1"
VERSION: int = 1
NO_ARG: int = 0xFFFFFFFF
_TAG_INT, _TAG_FLOAT, _TAG_STRING, _TAG_BOOL = 0x01, 0x02, 0x03, 0x04


def dumps(program: Program) -> bytes:
    """Serialize ``program`` deterministically to the MVM1 binary format."""
    body = bytearray([VERSION])
    body += _pack(">H", len(program.names))
    for name in program.names:
        raw = _encode_text(name)
        body += _pack(">H", len(raw)) + raw
    body += _pack(">H", len(program.constants))
    for value in program.constants:
        body += _encode_constant(value)
    body += _pack(">I", len(program.instructions))
    for instr in program.instructions:
        body += bytes([_opcode_number(instr.op)]) + _pack(">I", _encode_arg(instr))
    checksum = zlib.crc32(bytes(body)) & 0xFFFFFFFF
    return MAGIC + bytes(body) + _pack(">I", checksum)


def loads(data: bytes) -> Program:
    """Parse MVM1 bytes into a Program, raising SerializationError on any defect."""
    body = _checked_body(bytes(data))
    reader = _Reader(body)
    version = reader.unpack(">B")
    if version != VERSION:
        raise SerializationError(f"unsupported format version {version}")
    names = [_read_name(reader) for _ in range(reader.unpack(">H"))]
    constants = [_read_constant(reader) for _ in range(reader.unpack(">H"))]
    instructions = [_read_instruction(reader) for _ in range(reader.unpack(">I"))]
    if reader.pos != len(body):
        raise SerializationError("trailing bytes after program body")
    return Program(constants=constants, names=names, instructions=instructions)


def _checked_body(data: bytes) -> bytes:
    """Verify magic and checksum; only then is the body safe to parse."""
    if len(data) < len(MAGIC) or data[:len(MAGIC)] != MAGIC:
        raise SerializationError("bad magic")
    if len(data) < len(MAGIC) + 1 + 4:
        raise SerializationError("truncated data")
    body = data[len(MAGIC):-4]
    (stored,) = struct.unpack(">I", data[-4:])
    if zlib.crc32(body) & 0xFFFFFFFF != stored:
        raise SerializationError("checksum mismatch")
    return body


class _Reader:
    """Bounds-checked sequential reader over the verified body."""

    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def take(self, count: int) -> bytes:
        if count < 0 or self.pos + count > len(self.data):
            raise SerializationError("truncated data")
        chunk = self.data[self.pos:self.pos + count]
        self.pos += count
        return chunk

    def unpack(self, fmt: str) -> int:
        (value,) = struct.unpack(fmt, self.take(struct.calcsize(fmt)))
        return int(value)

    def unpack_float(self) -> float:
        (value,) = struct.unpack(">d", self.take(8))
        return float(value)


def _read_name(reader: _Reader) -> str:
    raw = reader.take(reader.unpack(">H"))
    return _decode_text(raw)


def _read_constant(reader: _Reader) -> object:
    tag = reader.unpack(">B")
    if tag == _TAG_INT:
        return reader.unpack(">q")
    if tag == _TAG_FLOAT:
        return reader.unpack_float()
    if tag == _TAG_STRING:
        return _decode_text(reader.take(reader.unpack(">I")))
    if tag == _TAG_BOOL:
        flag = reader.unpack(">B")
        if flag not in (0, 1):
            raise SerializationError(f"invalid BOOL payload {flag}")
        return flag == 1
    raise SerializationError(f"unknown constant tag 0x{tag:02x}")


def _read_instruction(reader: _Reader) -> Instr:
    number = reader.unpack(">B")
    if not 1 <= number <= len(OPCODES):
        raise SerializationError(f"unknown opcode number {number}")
    op = OPCODES[number - 1]
    arg = reader.unpack(">I")
    if op in ARGUMENT_OPCODES:
        if arg == NO_ARG:
            raise SerializationError(f"{op} requires an argument")
        return Instr(op, arg)
    if arg != NO_ARG:
        raise SerializationError(f"{op} must not carry an argument")
    return Instr(op, None)


def _encode_constant(value: object) -> bytes:
    if type(value) is bool:
        return bytes([_TAG_BOOL, 1 if value else 0])
    if type(value) is int:
        return bytes([_TAG_INT]) + _pack(">q", value)
    if type(value) is float:
        return bytes([_TAG_FLOAT]) + struct.pack(">d", value)
    if type(value) is str:
        raw = _encode_text(value)
        return bytes([_TAG_STRING]) + _pack(">I", len(raw)) + raw
    raise SerializationError(f"unsupported constant {value!r}")


def _encode_arg(instr: Instr) -> int:
    if instr.op in ARGUMENT_OPCODES:
        if instr.arg is None or instr.arg == NO_ARG:
            raise SerializationError(f"{instr.op} needs an argument below 0xFFFFFFFF")
        return instr.arg
    if instr.arg is not None:
        raise SerializationError(f"{instr.op} takes no argument")
    return NO_ARG


def _opcode_number(op: str) -> int:
    if op not in OPCODE_NUMBERS:
        raise SerializationError(f"unknown opcode {op!r}")
    return OPCODE_NUMBERS[op]


def _pack(fmt: str, value: int) -> bytes:
    try:
        return struct.pack(fmt, value)
    except struct.error as exc:
        raise SerializationError(f"value {value!r} does not fit in {fmt}") from exc


def _encode_text(text: str) -> bytes:
    try:
        return text.encode("utf-8")
    except UnicodeEncodeError as exc:
        raise SerializationError("text is not valid UTF-8") from exc


def _decode_text(raw: bytes) -> str:
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SerializationError("invalid UTF-8 text") from exc

"""Human-readable listing of compiled Programs."""

from __future__ import annotations

from .compiler import Instr, Program
from .opcodes import ARGUMENT_OPCODES  # noqa: F401  (documents which opcodes show an argument)


def disassemble(program: Program) -> str:
    """Return one line per instruction, each terminated by a newline."""
    return "".join(
        _format_line(index, instr, program)
        for index, instr in enumerate(program.instructions)
    )


def _format_line(index: int, instr: Instr, program: Program) -> str:
    text = f"{index:04d} {instr.op}"
    if instr.arg is None:
        return text + "\n"
    text += f" {instr.arg}"
    if instr.op == "CONST":
        text += "  ; " + _render_constant(program, instr.arg)
    return text + "\n"


def _render_constant(program: Program, index: int) -> str:
    if not 0 <= index < len(program.constants):
        return "<invalid constant>"
    value = program.constants[index]
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is str:
        return '"' + _escape(value) + '"'
    return str(value)


def _escape(text: str) -> str:
    replacements = {"\\": "\\\\", '"': '\\"', "\n": "\\n", "\t": "\\t"}
    return "".join(replacements.get(ch, ch) for ch in text)

"""Command-line interface: ``python -m microvm COMMAND ...``."""

from __future__ import annotations

import argparse
import sys
from collections.abc import Callable
from pathlib import Path

from .compiler import compile_source
from .disassembler import disassemble
from .errors import MicroVMError
from .serializer import dumps, loads
from .vm import execute

DEFAULT_STEP_LIMIT = 100_000


class _UsageError(Exception):
    """Unreadable file or other usage problem; maps to exit code 2."""


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}") from exc
    if value < 1:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}")
    return value


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="microvm", description="MicroVM bytecode tools")
    sub = parser.add_subparsers(dest="command", required=True)

    run = sub.add_parser("run", help="compile a source file and execute it")
    run.add_argument("file")
    run.add_argument("--optimize", action="store_true")
    run.add_argument("--step-limit", type=_positive_int, default=DEFAULT_STEP_LIMIT)

    build = sub.add_parser("build", help="compile a source file to binary")
    build.add_argument("file")
    build.add_argument("out")
    build.add_argument("--optimize", action="store_true")

    exec_cmd = sub.add_parser("exec", help="execute a compiled binary")
    exec_cmd.add_argument("file")
    exec_cmd.add_argument("--step-limit", type=_positive_int, default=DEFAULT_STEP_LIMIT)

    disasm = sub.add_parser("disasm", help="disassemble a compiled binary")
    disasm.add_argument("file")
    return parser


def main(argv: list[str] | None = None) -> int:
    """Run the CLI and return the process exit code."""
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    handlers: dict[str, Callable[[argparse.Namespace], int]] = {
        "run": _cmd_run,
        "build": _cmd_build,
        "exec": _cmd_exec,
        "disasm": _cmd_disasm,
    }
    try:
        return handlers[args.command](args)
    except _UsageError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except MicroVMError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 3


def _cmd_run(args: argparse.Namespace) -> int:
    program = compile_source(_read_text(args.file), optimize=args.optimize)
    return _emit(execute(program, step_limit=args.step_limit))


def _cmd_build(args: argparse.Namespace) -> int:
    program = compile_source(_read_text(args.file), optimize=args.optimize)
    _write_bytes(args.out, dumps(program))
    return 0


def _cmd_exec(args: argparse.Namespace) -> int:
    program = loads(_read_bytes(args.file))
    return _emit(execute(program, step_limit=args.step_limit))


def _cmd_disasm(args: argparse.Namespace) -> int:
    sys.stdout.write(disassemble(loads(_read_bytes(args.file))))
    return 0


def _emit(lines: list[str]) -> int:
    """Print output only after the whole run succeeded."""
    sys.stdout.write("".join(line + "\n" for line in lines))
    return 0


def _read_text(path: str) -> str:
    try:
        return Path(path).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise _UsageError(f"cannot read {path}: {exc}") from exc


def _read_bytes(path: str) -> bytes:
    try:
        return Path(path).read_bytes()
    except OSError as exc:
        raise _UsageError(f"cannot read {path}: {exc}") from exc


def _write_bytes(path: str, data: bytes) -> None:
    try:
        Path(path).write_bytes(data)
    except OSError as exc:
        raise _UsageError(f"cannot write {path}: {exc}") from exc


